order by order_time desc

select * from orders


    and number like concat('%',#{number},'%')


    and phone like concat('%',#{phone},'%')


    and status = #{status}


    and status not in (5, 6)


    and order_time >= #{beginTime}


    and order_time <= #{endTime}


order by order_time desc

select count(id) from orders


        and order_time > #{begin}


        and order_time < #{end}


        and status = #{status}

select sum(amount) from orders


        and order_time > #{begin}


        and order_time < #{end}


        and status = #{status}

select date_format(order_time, '%Y-%m-%d') as stat_date, count(id) as stat_value
from orders
where order_time >= #{begin} and order_time < #{end}

    and status = #{status}

group by stat_date

select date_format(order_time, '%Y-%m-%d') as stat_date, sum(amount) as stat_value
from orders
where order_time >= #{begin} and order_time < #{end}

    and status = #{status}

group by stat_date

select od.name, sum(od.number) number from order_detail od,orders o where od.order_id = o.id and o.status = 5
and o.order_time > #{begin}
and o.order_time < #{end}
group by od.name order by number desc limit 0,10

